-- places/locate-point
-- Which district and local unit contain a point (longitude, latitude). No row means the point is
-- outside Nepal's official border. The local unit is null inside a national park or reserve.
--
-- Parameters, with the example values used to render this file:
--   $1 = 85.324
--   $2 = 27.7172
--   $3 = 85.324
--   $4 = 27.7172
--
-- Generated by `pnpm db:queries` from lib/db/queries/places.ts. Do not edit by hand.

select d.id as district_id, d.name_en as district_en, d.name_np as district_np,
       lu.id as local_unit_id, lu.name_en as local_unit_en, lu.name_np as local_unit_np
from districts d
left join local_units lu
  on lu.district_id = d.id and ST_Covers(lu.geom, ST_SetSRID(ST_MakePoint($1, $2), 4326))
where ST_Covers(d.geom, ST_SetSRID(ST_MakePoint($3, $4), 4326))
limit 1;
